import {
  Mesh,
  PlaneGeometry,
  Object3D,
  Color,
  Vector3,
  Euler,
} from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

export default function createNode(config, ctx) {
  // Root container
  const node = new Object3D();

  // Geometry & Texture
  const geometry = new PlaneGeometry(1, 1);
  const texture = ctx.textureLoader.load(config.assets.imageUrl);
  texture.anisotropy = 8;
  texture.encoding = ctx.renderer?.outputEncoding ?? undefined;

  // Material
  const material = new MeshBasicNodeMaterial({ map: texture, color: new Color(0xffffff) });

  // Mesh
  const mesh = new Mesh(geometry, material);
  mesh.position.set(
    (config.scenePlacement?.position?.[0] ?? 0),
    (config.scenePlacement?.position?.[1] ?? 0),
    (config.scenePlacement?.position?.[2] ?? 0),
  );
  mesh.rotation.set(
    (config.scenePlacement?.rotation?.[0] ?? 0),
    (config.scenePlacement?.rotation?.[1] ?? 0),
    (config.scenePlacement?.rotation?.[2] ?? 0),
  );
  mesh.scale.set(
    (config.scenePlacement?.scale?.[0] ?? 1),
    (config.scenePlacement?.scale?.[1] ?? 1),
    (config.scenePlacement?.scale?.[2] ?? 1),
  );
  node.add(mesh);

  // Stock badge (placeholder for data binding)
  const badgeGeometry = new PlaneGeometry(0.4, 0.2);
  const badgeMaterial = new MeshBasicNodeMaterial({
    color: new Color(config.colors?.accent ?? '#ff2a38'),
    transparent: true,
    opacity: 0.9,
  });
  const badge = new Mesh(badgeGeometry, badgeMaterial);
  badge.position.set(0, -0.6, 0.01);
  badge.visible = false;
  mesh.add(badge);
  node.userData.stockBadge = badge; // expose for external binding

  // Interaction handlers storage
  const handlers = {};

  // Hover - rise-in effect (subtle lift of 0.15 units)
  const hoverRise = 0.15;
  const hoverTimeline = gsap.timeline({ paused: true });
  hoverTimeline.to(mesh.position, {
    y: mesh.position.y + hoverRise,
    duration: 0.7,
    ease: 'power3.out',
  });

  handlers.hover = {
    enter() {
      hoverTimeline.play();
    },
    leave() {
      hoverTimeline.reverse();
    },
  };

  // Click - emit event
  handlers.click = () => {
    if (typeof ctx.emit === 'function') {
      ctx.emit('hub-journal.select');
    }
  };

  // Attach handlers to userData for external system
  node.userData.handlers = handlers;

  // Cleanup
  node.userData.cleanup = () => {
    // Dispose geometry & material
    geometry.dispose();
    material.dispose();
    texture.dispose();

    badgeGeometry.dispose();
    badgeMaterial.dispose();

    // Kill GSAP timelines
    hoverTimeline.kill();
  };

  return node;
}
